// One source of truth for the design tokens: the Waffles token files (web/tokens/waffles/, copied unchanged)
// plus SQL Drills' layer (web/tokens/sqldrills.json: fonts and the light / dark theme roles).
// Writes, into web/src/tokens/ (generated, do not edit by hand):
//   tokens.css   CSS custom properties: :root (light) and :root[data-theme="dark"]
//   _tokens.scss SCSS variables (raw values for Sass maths; theme colours as var(--wf-…)) and breakpoint mixins
//   tokens.js    the same for JavaScript / Emotion (theme colours as var(--wf-…), so they follow dark mode)
//   tokens.json  every token resolved to a plain value per theme (used by the tests and the contrast audit)
// Deprecated Waffles tokens (attributes.deprecated) are left out.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const web = fileURLToPath(new URL("../", import.meta.url));
const SRC = path.join(web, "tokens/waffles"), OUT = path.join(web, "src/tokens");
const ours = JSON.parse(fs.readFileSync(path.join(web, "tokens/sqldrills.json"), "utf8"));

// ---- read and merge the Waffles files ----
const merge = (a, b) => { for (const k of Object.keys(b)) a[k] = b[k] && typeof b[k] === "object" && !("value" in b[k]) ? merge(a[k] || {}, b[k]) : b[k]; return a; };
const files = (d) => fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => e.isDirectory() ? files(path.join(d, e.name)) : e.name.endsWith(".json") ? [path.join(d, e.name)] : []);
const W = files(SRC).sort().reduce((acc, f) => merge(acc, JSON.parse(fs.readFileSync(f, "utf8"))), {});
const live = (group) => Object.entries(group || {}).filter(([, t]) => !(t.attributes && t.attributes.deprecated));

const kebab = (s) => String(s).replace(/([a-z])([A-Z0-9])/g, "$1-$2").replace(/([0-9])([a-zA-Z])/g, "$1-$2").toLowerCase();
const hex = (c) => "#" + [c.r, c.g, c.b].map((n) => n.toString(16).padStart(2, "0")).join("").toUpperCase();
const px = (v) => (typeof v === "number" && v !== 0 ? v + "px" : String(v));

// ---- colours: Waffles names → hex ----
const palette = {};
for (const [name, t] of live(W.color.primary)) palette[name] = hex(t.value);
for (const [name, t] of live(W.color.neutral)) palette[name] = hex(t.value);
const FAMILIES = Object.keys(palette).filter((n) => palette[n + "Text"]);
const colour = (v) => (palette[v] ? palette[v] : v); // a Waffles name, or our own value

// ---- static tokens (same in both themes) ----
const vars = {}; // css name (without --wf-) → value
for (const [name, v] of Object.entries(palette)) vars["color-" + kebab(name)] = v;
for (const [k, t] of live(W.size.space)) vars["space-" + k] = px(t.value);
for (const [k, t] of live(W.radii)) vars["radius-" + kebab(k)] = px(t.value);
for (const [k, t] of live(W.shadow)) vars["shadow-" + kebab(k)] = String(t.value).replace("{shadow.color.value}", "var(--wf-shadow-color)");
for (const [k, t] of live(W.size.font)) vars["font-size-" + k] = k === "base" ? t.value : t.value + "rem";
for (const [k, t] of live(W.lineHeight)) vars["line-height-" + kebab(k)] = String(t.value);
for (const [k, t] of live(W.letterSpacings)) vars["letter-spacing-" + kebab(k)] = px(t.value);
for (const [k, t] of live(W.fontWeight)) vars["font-weight-" + k] = String(ours.fontWeight[k] || t.value);
for (const [k, t] of live(W.opacity)) vars["opacity-" + k] = String(t.value);
for (const [k, t] of live(W.zIndex)) vars["z-" + k] = String(t.value);
vars["font-sans"] = ours.font.sans;
vars["font-mono"] = ours.font.mono;
const breakpoints = Object.fromEntries(live(W.breakpoints).sort((a, b) => a[1].attributes.scssSortValue - b[1].attributes.scssSortValue).map(([k, t]) => [k, t.value]));
for (const [k, v] of Object.entries(breakpoints)) vars["breakpoint-" + kebab(k)] = v;

// ---- themes ----
const theme = (name) => {
  const t = {};
  for (const [role, v] of Object.entries(ours.themes[name])) t[role] = colour(v);
  const tv = (ours.textVariants || {})[name] || {};
  for (const f of FAMILIES) t["color-" + kebab(f) + "-text"] = colour(tv[f] || palette[f + "Text"]); // "_note" keys are ignored
  return t;
};
const light = theme("light"), dark = theme("dark");

// ---- write ----
fs.mkdirSync(OUT, { recursive: true });
const HEAD = "Generated by web/tools/build-tokens.mjs from web/tokens/ (Waffles tokens + sqldrills.json). Do not edit by hand.";
const block = (sel, obj) => sel + " {\n" + Object.entries(obj).map(([k, v]) => "  --wf-" + k + ": " + v + ";").join("\n") + "\n}\n";
// the Waffles palette as the Waffles components use it (--wf-w-<name>), light and dark (see sqldrills.json wafflesPalette)
const WP = ours.wafflesPalette;
const wpal = (name) => Object.fromEntries(Object.keys(palette).map((n) => [n, colour((WP[name] || {})[n] || palette[n])]));
const wLight = wpal("light"), wDark = { ...wLight, ...wpal("dark") };
for (const n of Object.keys(palette)) if (!(WP.dark || {})[n]) wDark[n] = wLight[n];
const wVars = (p) => Object.fromEntries([...Object.entries(p).map(([n, v]) => ["w-" + kebab(n), v]), ...Object.entries(WP.fixed).map(([k, v]) => ["w-" + k, colour(v)])]);
fs.writeFileSync(path.join(OUT, "tokens.css"), "/* " + HEAD + " */\n" + block(":root", { ...vars, ...light, ...wVars(wLight) }) + block(':root[data-theme="dark"]', { ...dark, ...wVars(wDark) }));

const themed = new Set(Object.keys(light));
const scssName = (k) => "$wf-" + k;
let scss = "// " + HEAD + "\n// Raw values (usable in Sass maths); theme colours are var(--wf-…) so they follow dark mode.\n@use \"sass:map\";\n";
for (const [k, v] of Object.entries(vars)) if (!themed.has(k)) scss += scssName(k) + ": " + v + ";\n";
for (const k of themed) scss += scssName(k) + ": var(--wf-" + k + ");\n";
scss += "$wf-breakpoints: (" + Object.entries(breakpoints).map(([k, v]) => '"' + k + '": ' + v).join(", ") + ");\n";
scss += "// from this width up\n@mixin wf-up($bp) { @media (min-width: map.get($wf-breakpoints, $bp)) { @content; } }\n";
scss += "// below this width\n@mixin wf-below($bp) { @media (max-width: (map.get($wf-breakpoints, $bp) - 0.02px)) { @content; } }\n";
fs.writeFileSync(path.join(OUT, "_tokens.scss"), scss);

const nest = (prefix) => Object.fromEntries(Object.keys(vars).filter((k) => k.startsWith(prefix)).map((k) => [k.slice(prefix.length), themed.has(k) || k.startsWith("color-") ? "var(--wf-" + k + ")" : vars[k]]));
const js = {
  color: nest("color-"), space: nest("space-"), radius: nest("radius-"), shadow: Object.fromEntries(Object.keys(nest("shadow-")).map((k) => [k, "var(--wf-shadow-" + k + ")"])),
  fontSize: nest("font-size-"), lineHeight: nest("line-height-"), letterSpacing: nest("letter-spacing-"), fontWeight: nest("font-weight-"),
  opacity: nest("opacity-"), z: nest("z-"), font: { sans: "var(--wf-font-sans)", mono: "var(--wf-font-mono)" }, breakpoints,
  role: Object.fromEntries(Object.keys(ours.themes.light).map((k) => [k, "var(--wf-" + k + ")"])),
};
for (const f of FAMILIES) js.color[kebab(f) + "-text"] = "var(--wf-color-" + kebab(f) + "-text)";
fs.writeFileSync(path.join(OUT, "tokens.js"), "// " + HEAD + "\nexport const tokens = " + JSON.stringify(js, null, 2) + ";\nexport default tokens;\n");

fs.writeFileSync(path.join(OUT, "tokens.json"), JSON.stringify({ _: HEAD, families: FAMILIES, static: vars, light, dark, roles: { surfaces: ours.surfaces, text: ours.textRoles, fills: ours.fills }, waffles: { light: wLight, dark: wDark, fixed: Object.fromEntries(Object.entries(WP.fixed).map(([k, v]) => [k, colour(v)])) } }, null, 2) + "\n");

// ---- the Waffles token files the Waffles sources import, same shapes and names as the original build ----
// (@datacamp/waffles-tokens: lib/future-tokens.json, lib/core-tokens.json, lib/variables.scss), with every
// colour as var(--wf-w-<name>) so the components follow dark mode, and IBM Plex in place of Waffles' font.
const WOUT = path.join(web, "src/waffles/tokens");
fs.mkdirSync(WOUT, { recursive: true });
const wvar = (n) => "var(--wf-w-" + kebab(n) + ")";
const FONT = { sansSerif: { value: "IBM Plex Sans", attributes: { fallback: "Arial, sans-serif" } }, mono: { value: "IBM Plex Mono", attributes: { fallback: "monospace" } } };
const strip = (o) => Object.fromEntries(Object.entries(o).filter(([, t]) => !(t && t.attributes && t.attributes.deprecated)).map(([k, t]) => [k, t && typeof t === "object" && !("value" in t) ? strip(t) : t]));
const colourObj = (group) => Object.fromEntries(live(group).map(([n]) => [n, { value: { hex: wvar(n), hex8: wvar(n), hsl: wvar(n), rgb: wvar(n) } }]));
const shadowVal = (v) => String(v).replace("{shadow.color.value}", "var(--wf-shadow-color)");
const future = strip({
  ...W,
  asset: { font: FONT },
  color: { primary: colourObj(W.color.primary), neutral: colourObj(W.color.neutral) },
  fontWeight: Object.fromEntries(Object.entries(W.fontWeight).map(([k, t]) => [k, { ...t, value: ours.fontWeight[k] || t.value }])),
  shadow: Object.fromEntries(Object.entries(W.shadow).map(([k, t]) => [k, { ...t, value: shadowVal(t.value) }])),
  size: { ...W.size, font: Object.fromEntries(Object.entries(W.size.font).map(([k, t]) => [k, { ...t, value: typeof t.value === "number" ? t.value * 16 + "px" : t.value }])) },
});
const valuesOf = (o) => Object.fromEntries(Object.entries(o).filter(([k]) => k !== "remove").map(([k, t]) => [k, t.value]));
const listOf = (o) => Object.values(o).map((t) => t.value);
const core = {
  animation: valuesOf(W.animation), border: valuesOf(W.size.border), boxShadow: Object.fromEntries(Object.entries(W.shadow).map(([k, t]) => [k, shadowVal(t.value)])),
  breakpoints: { ...valuesOf(W.breakpoints), ...Object.fromEntries(Object.entries(W.breakpoints).map(([k, t]) => ["below" + k.charAt(0).toUpperCase() + k.slice(1), t.attributes.below])) },
  colors: Object.fromEntries(Object.keys(palette).map((n) => [n, wvar(n)])),
  fontFamily: { sansSerif: "'IBM Plex Sans'", mono: "'IBM Plex Mono'" },
  fontSize: Object.fromEntries(Object.entries(W.size.font).filter(([, t]) => t.attributes && t.attributes.legacyName).map(([, t]) => [t.attributes.legacyName, typeof t.value === "string" ? t.value : t.value + "rem"])),
  fontWeight: Object.fromEntries(Object.entries(W.fontWeight).map(([k, t]) => [k, String(ours.fontWeight[k] || t.value)])),
  letterSpacings: valuesOf(W.letterSpacings), lineHeight: valuesOf(W.lineHeight),
  spatial: { angles: listOf(W.size.spatial.angle).join(" "), commonSizes: listOf(W.size.spatial.commonSize).join(" ").replace(/\{size\.spatial\.size\.(\d+)\.value\}/g, "$1"), measure: listOf(W.size.spatial.measure).join(" "), multiplier: W.size.spatial.multiplier.value, percentages: listOf(W.size.spatial.percentage).join(" "), sizes: listOf(W.size.spatial.size).join(" "), zIndex: listOf(W.zIndex).join(" ") },
};
const GEN = "// " + HEAD + "\n// Same shape as the Waffles token build output it replaces; colours are CSS variables (light/dark).\n";
fs.writeFileSync(path.join(WOUT, "future-tokens.js"), GEN + "const tokens = " + JSON.stringify(future, null, 2) + ";\nexport default tokens;\n");
fs.writeFileSync(path.join(WOUT, "core-tokens.js"), GEN + "const tokens = " + JSON.stringify(core, null, 2) + ";\nexport default tokens;\n");

// variables.scss: the $dc-* names of the Waffles SCSS build. Colours are var(--wf-w-*) (dark mode); the raw light
// value of each is also there as $dc-raw-<name>, for Sass colour functions that need a real colour.
const sv = [], line = (k, v) => sv.push("$dc-" + k + ": " + v + ";");
line("multiplier", W.size.spatial.multiplier.value);
line("spatial", listOf(W.size.spatial.size).join(" "));
line("spatial-common", listOf(W.size.spatial.commonSize).join(" ").replace(/\{size\.spatial\.size\.(\d+)\.value\}/g, "$1"));
line("measure", listOf(W.size.spatial.measure).join(" "));
sv.push("$dc-spatial-all: list.join($dc-spatial, $dc-measure);");
line("percentages", listOf(W.size.spatial.percentage).join(" "));
line("angles", listOf(W.size.spatial.angle).join(" "));
line("z-indexes", listOf(W.zIndex).join(" "));
for (const n of Object.keys(palette)) { line(kebab(n), wvar(n)); line("raw-" + kebab(n), wLight[n]); }
sv.push("$dc-colors: (\n  'currentColor': currentColor,\n  'transparent': transparent,\n" + Object.keys(palette).map((n) => "  '" + kebab(n) + "': $dc-" + kebab(n) + ",").join("\n") + "\n);");
line("on-fill", "var(--wf-w-on-fill)");
for (const [k, t] of Object.entries(FONT)) line("font-family-" + kebab(k), '"' + t.value + '", ' + t.attributes.fallback);
for (const [, t] of Object.entries(W.size.font)) if (t.attributes && t.attributes.legacyName) line("font-size-" + t.attributes.legacyName, typeof t.value === "string" ? t.value : t.value + "rem");
for (const [k, t] of Object.entries(W.fontWeight)) line("font-weight-" + kebab(k), ours.fontWeight[k] || t.value);
for (const [k, t] of Object.entries(W.lineHeight)) line("line-height-" + kebab(k), t.value);
for (const [k, t] of Object.entries(W.size.border)) line("border-" + kebab(k), t.value);
for (const [k, t] of Object.entries(W.shadow)) line("box-shadow-" + kebab(k), shadowVal(t.value));
for (const [k, t] of Object.entries(W.animation)) line(kebab(k), t.value);
for (const [k, t] of Object.entries(W.letterSpacings)) line("letter-spacing-" + kebab(k), t.value + "px");
const bpKey = (k) => kebab(k).replace(/([1-9]+)-k$/, "$1k");
const bps = Object.entries(W.breakpoints).sort((a, b) => a[1].attributes.scssSortValue - b[1].attributes.scssSortValue);
for (const [k, t] of bps) line("bp-" + bpKey(k), t.value);
for (const [k, t] of bps) line("bp-below-" + bpKey(k), t.attributes.below);
const bmap = (name, hd, below) => sv.push("$dc-" + name + ": (\n" + bps.filter(([, t]) => !!t.attributes.hd === hd).map(([k]) => "  '" + bpKey(k) + "': $dc-bp-" + (below ? "below-" : "") + bpKey(k) + ",").join("\n") + "\n);");
bmap("breakpoints", false, false); bmap("breakpoints-hd", true, false);
sv.push("$dc-breakpoints-all: map.merge($dc-breakpoints, $dc-breakpoints-hd);");
bmap("breakpoints-below", false, true); bmap("breakpoints-below-hd", true, true);
sv.push("$dc-breakpoints-below-all: map.merge($dc-breakpoints-below, $dc-breakpoints-below-hd);");
sv.push("$dc-sides: ('t': top, 'r': right, 'b': bottom, 'l': left);");
fs.writeFileSync(path.join(WOUT, "_variables.scss"), GEN + '@use "sass:list";\n@use "sass:map";\n' + sv.join("\n") + "\n");
console.log("waffles tokens: future-tokens.js, core-tokens.js, _variables.scss (" + sv.length + " variables) → " + path.relative(web, WOUT));
console.log("tokens:", Object.keys(vars).length, "static,", Object.keys(light).length, "per theme,", FAMILIES.length, "colour families →", path.relative(web, OUT));

// palette.js: each --wf-w-* variable's real colour per theme, for code that must compute with a colour
// (hexColorLuminance, hexToRgbaColor in the Waffles utils).
const palJs = (p) => Object.fromEntries([...Object.entries(p).map(([n, v]) => ["--wf-w-" + kebab(n), v]), ...Object.entries(WP.fixed).map(([k, v]) => ["--wf-w-" + k, colour(v)])]);
fs.writeFileSync(path.join(WOUT, "palette.js"), GEN + "export const palette = " + JSON.stringify({ light: palJs(wLight), dark: palJs(wDark) }, null, 2) + ";\nexport default palette;\n");
